interface BrandIconProps extends SVGProps<SVGSVGElement> {
  name: IconName;
}

export function BrandIcon({ name, ...props }: BrandIconProps) {
  const icon = BRAND_ICONS[name];
  if (!icon) return null;
  return (
    <svg
      viewBox="0 0 24 24"
      fill="currentColor"
      aria-hidden="true"
      {...props}
    >
      <path d={icon.path} />
    </svg>
  );
}
